"import "./ColorPalettePicker.css";

interface ColorPalettePickerProps {
  colors: string[];
  onChange: (colors: string[]) => void;
  error?: string;
  minColors?: number;
}

const MAX_COLORS = 10;

function ColorPalettePicker({
  colors,
  onChange,
  error,
  minColors = 5,
}: ColorPalettePickerProps) {
  function handleColorChange(index: number, value: string) {
    const updated = [...colors];
    updated[index] = value;
    onChange(updated);
  }

  function addColor() {
    if (colors.length < MAX_COLORS) {
      onChange([...colors, "#000000"]);
    }
  }

  function removeColor(index: number) {
    onChange(colors.filter((_, i) => i !== index));
  }

  return (
    <div className="cpp-wrapper">
      <div className="cpp-swatches">
        {colors.map((color, i) => (
          <div key={i} className="cpp-swatch-item">
            <div
              className="cpp-swatch"
              style={{ backgroundColor: color }}
            >
              <input
                type="color"
                className="cpp-color-input"
                value={color}
                onChange={(e) => handleColorChange(i, e.target.value)}
                title={color}
              />
            </div>
            <span className="cpp-hex">{color}</span>
            <button
              type="button"
              className="cpp-remove-btn"
              onClick={() => removeColor(i)}
              aria-label="Remove color"
            >
              ×
            </button>
          </div>
        ))}

        {colors.length < MAX_COLORS && (
